// Uplink protocol router + Cayenne LPP decoder.
// env.protocol: "custom"  = RAK4631 Android binary frame (14 bytes)
//               "cayenne" = RUI3 sensor, Cayenne LPP
//               "auto"    = a frame that is strictly valid Cayenne LPP for the
//                           RUI3 firmware channel map is Cayenne, else custom
// Output 1: custom frame (msg.payload = Buffer), output 2: decoded Cayenne
// (msg.payload = object with logical field names).
const CHANNELS = {
  1: 'battery_voltage', 2: 'temperature', 3: 'humidity', 4: 'pressure',
  5: 'illuminance', 6: 'accelerometer', 7: 'version_byte', 8: 'acc_threshold',
  9: 'acc_duration', 10: 'acc_frequency', 11: 'motion_switch',
  12: 'motion_alert', 13: 'low_battery_shutdown', 14: 'gas_resistance'
};
const TYPE_NAMES = {
  0x00: 'digital_input', 0x01: 'digital_output', 0x8E: 'switch_output',
  0x65: 'illuminance', 0x67: 'temperature', 0x68: 'humidity',
  0x71: 'accelerometer', 0x73: 'barometric_pressure', 0x74: 'battery_voltage',
  0x86: 'gyrometer', 0x88: 'gps', 0x8A: 'gas_resistance'
};
// Cayenne LPP type -> data size in bytes
const SIZES = {
  0x00: 1, 0x01: 1, 0x8E: 1, 0x65: 2, 0x67: 2, 0x68: 1,
  0x71: 6, 0x73: 2, 0x74: 2, 0x86: 6, 0x88: 9, 0x8A: 2
};
// Types the RUI3 firmware sends per channel (used by "auto" only)
const FIRMWARE_TYPES = {
  1: [0x74], 2: [0x67], 3: [0x68], 4: [0x73], 5: [0x65], 6: [0x71],
  7: [0x00], 8: [0x00], 9: [0x00], 10: [0x00], 11: [0x00, 0x01, 0x8E],
  12: [0x00, 0x01], 13: [0x00, 0x01], 14: [0x8A]
};

const u16 = (b, i) => (b[i] << 8) | b[i + 1];
const s16 = (b, i) => { const v = u16(b, i); return v >= 0x8000 ? v - 0x10000 : v; };
const s24 = (b, i) => { const v = (b[i] << 16) | (b[i + 1] << 8) | b[i + 2]; return v >= 0x800000 ? v - 0x1000000 : v; };

function value(type, b, i) {
  switch (type) {
    case 0x00: case 0x01: case 0x8E: return b[i];
    case 0x65: case 0x8A: return u16(b, i);
    case 0x67: return s16(b, i) / 10;           // 0.1 C
    case 0x68: return b[i] / 2;                 // 0.5 %
    case 0x73: return u16(b, i) / 10;           // 0.1 hPa
    case 0x74: return u16(b, i) / 100;          // 0.01 V
    case 0x71: return { x: s16(b, i) / 1000, y: s16(b, i + 2) / 1000, z: s16(b, i + 4) / 1000 };
    case 0x86: return { x: s16(b, i) / 100, y: s16(b, i + 2) / 100, z: s16(b, i + 4) / 100 };
    case 0x88: return { latitude: s24(b, i) / 10000, longitude: s24(b, i + 3) / 10000, altitude: s24(b, i + 6) / 100 };
  }
}

// strict: return null unless the whole buffer is valid. Otherwise decode
// as far as possible and warn on the first bad record.
function decode(b, strict) {
  const out = {};
  let i = 0;
  while (i < b.length) {
    const ch = b[i];
    const type = b[i + 1];
    const size = SIZES[type];
    if (i + 1 >= b.length || size === undefined || i + 2 + size > b.length) {
      if (strict) return null;
      node.warn('Cayenne: unknown or truncated record (type 0x' + Number(type).toString(16) + ', channel ' + ch + ') at byte ' + i);
      break;
    }
    if (strict && !(FIRMWARE_TYPES[ch] || []).includes(type)) return null;
    out[CHANNELS[ch] || (TYPE_NAMES[type] + '_' + ch)] = value(type, b, i + 2);
    i += 2 + size;
  }
  if (strict && Object.keys(out).length === 0) return null;
  return out;
}

const cfg = String(env.get('protocol') || 'auto').toLowerCase();
const buf = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(String(msg.payload || ''), 'hex');
if (buf.length === 0) return null;

let decoded = null;
let proto = cfg;
if (cfg === 'auto') {
  decoded = decode(buf, true);
  proto = decoded ? 'cayenne' : 'custom';
} else if (cfg === 'cayenne') {
  decoded = decode(buf, false);
} else if (cfg !== 'custom') {
  node.error('Unknown protocol "' + cfg + '" (use custom, cayenne or auto)', msg);
  return null;
}

flow.set('protocolSeen', proto);
if (proto === 'custom') {
  if (buf.length < 14) {
    node.warn('Custom frame too short (' + buf.length + ' bytes, need 14), ignored');
    return null;
  }
  return [msg, null];
}
msg.payload = decoded;
return [null, msg];

// Split a decoded Cayenne uplink into the same per-field messages the custom
// buffer-parser branch produces, so the shared downstream nodes can be reused.
const d = msg.payload || {};
const has = (k) => d[k] !== undefined && d[k] !== null;
const out = new Array(12).fill(null);

if (has('battery_voltage')) out[0] = { payload: d.battery_voltage };                    // already in volts
if (has('temperature')) out[1] = { payload: d.temperature - (Number(env.get('Tk')) || 0) };
if (d.accelerometer && typeof d.accelerometer === 'object') {
  out[2] = { payload: d.accelerometer.x, topic: 'xAxis' };
  out[3] = { payload: d.accelerometer.y, topic: 'yAxis' };
  out[4] = { payload: d.accelerometer.z, topic: 'zAxis' };
}
// same shape as "Status Byte Decode" of the custom frame
const status = {};
if (has('motion_switch')) status.ALARM_SW = Number(d.motion_switch) === 1;
if (has('motion_alert')) status.ALARM_ACC = Number(d.motion_alert) !== 0;
if (Object.keys(status).length) out[5] = { payload: status };
if (has('version_byte')) out[6] = { payload: d.version_byte };
if (has('acc_threshold')) out[7] = { payload: d.acc_threshold };
if (has('acc_duration')) out[8] = { payload: d.acc_duration };
if (has('acc_frequency')) out[9] = { payload: d.acc_frequency };
if (has('humidity')) out[10] = { payload: d.humidity };
const extra = [];
if (has('pressure')) extra.push({ topic: 'pressure', payload: d.pressure });
if (has('illuminance')) extra.push({ topic: 'illuminance', payload: d.illuminance });
if (has('gas_resistance')) extra.push({ topic: 'gas', payload: d.gas_resistance });
if (extra.length) out[11] = extra;
return out;

// Circuit/switch state as text for the dashboard
if (!msg.payload || typeof msg.payload.ALARM_SW !== 'boolean') return null;
return { topic: 'circuitStatus', payload: msg.payload.ALARM_SW ? '\u00f6ppen' : 'sluten' };

// RUI3 firmware reports the accelerometer ODR as an index (LIS3DH data rate)
const HZ = { 1: 1, 2: 10, 3: 25, 4: 50, 5: 100, 6: 200, 7: 400 };
const idx = parseInt(msg.payload, 10);
msg.original = idx;
msg.payload = HZ[idx] !== undefined ? HZ[idx] : 0;
return msg;

// Dashboard frequency codes are the custom (RAK4631) LIS3DH register values.
// RUI3 sensors expect the ODR index 1-7 on the same port.
const cfg = String(env.get('protocol') || 'auto').toLowerCase();
const proto = cfg === 'auto' ? flow.get('protocolSeen') : cfg;
if (proto === 'custom') return msg;
if (proto !== 'cayenne') {
  node.warn('Frequency downlink not sent: protocol not known yet, wait for the first uplink or set protocol explicitly');
  return null;
}
const MAP = { 0: 0, 31: 1, 47: 2, 63: 3, 79: 4, 95: 5 };
const code = parseInt(msg.payload, 10);
let idx;
if (MAP[code] !== undefined) idx = MAP[code];
else if (code >= 1 && code <= 7) idx = code;
else {
  node.warn('Unknown frequency code: ' + msg.payload);
  return null;
}
msg.payload = String(idx).padStart(3, '0');
return msg;
